"""Self-contained workspace styles. System fonts, no remote assets."""
CSS = """
:root{color-scheme:dark;--bg:#101113;--panel:#19191e;--line:#2b2b33;--fg:#eeedf2;--dim:#a5a3b0;--gold:#daa7d4;--red:#f19a9c;--green:#87dec3;--blue:#a5bafb;--accent:#c892ce}
*{box-sizing:border-box}html{scroll-padding-top:24px}body{margin:0;background:var(--bg);color:var(--fg);font:13px/1.55 'Segoe UI',system-ui,-apple-system,sans-serif}a{color:var(--gold)}button,select,textarea{font:inherit}button{cursor:pointer}button:disabled{cursor:not-allowed;opacity:.45}:focus-visible{outline:2px solid var(--gold);outline-offset:4px}::selection{background:#73466f;color:white}[hidden]{display:none!important}
h1,h2,h3,p{margin:0}h1{font-size:25px;font-weight:550;letter-spacing:-.04em}h2{font-size:16px;font-weight:550;letter-spacing:-.025em;margin-bottom:14px}h3{font-size:13px;margin:12px 0 8px}p{margin:8px 0}small,.small{font-size:11px}.dim{color:var(--dim)}.ok{color:var(--green)}.bad{color:var(--red)}.warn{color:var(--gold)}.eyebrow{font-size:10px;color:var(--dim);letter-spacing:.08em;text-transform:uppercase}.pill{display:inline-block;padding:4px 9px;border:1px solid var(--line);border-radius:5px;font-size:10px;font-weight:500;letter-spacing:.03em;white-space:nowrap}.pill.warn{background:#31232f;border-color:#52334e}.pill.ok{background:#1b322c;border-color:#2b4b40}.pill.bad{background:#382329;border-color:#62363d}
.skip-link{position:fixed;top:-100px;left:16px;background:var(--fg);color:var(--bg);padding:12px;z-index:10}.skip-link:focus{top:12px}
.sidebar{position:fixed;inset:0 auto 0 0;width:188px;padding:28px 16px 20px;background:#121214;border-right:1px solid #25252b;display:flex;flex-direction:column;z-index:3}.wordmark{display:flex;align-items:center;text-decoration:none;color:var(--fg);font-size:24px;font-weight:700;letter-spacing:-1px;padding:0 7px}.wordmark-dot{color:var(--accent)}.brand-mark{display:grid;place-items:center;width:29px;height:29px;margin-right:8px;border-radius:6px;background:#352638;color:var(--gold);font:600 18px ui-monospace,Consolas,monospace;letter-spacing:-2px}.workspace-label{display:flex;align-items:center;gap:8px;margin:30px 0;padding:12px 4px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);font-size:11px}.workspace-label small{display:block;color:var(--dim);font-size:10px}.workspace-icon{display:grid;place-items:center;flex-shrink:0;width:29px;height:30px;border:1px solid #43404d;border-radius:7px;background:#27242d;color:#ddd1ea}.nav-label{display:block;color:#92909f;font-size:10px;text-transform:uppercase;letter-spacing:.12em;margin:0 12px 14px}.sidebar nav a{display:flex;gap:12px;align-items:center;padding:10px 12px;margin:3px 0;border-radius:6px;color:#aaa7b4;text-decoration:none;font-size:12px}.sidebar nav a span{width:15px;text-align:center;font-size:17px;line-height:1}.sidebar nav a:hover{background:#1e1d23;color:var(--fg)}.sidebar nav a[aria-current]{background:#30242f;color:#edc4e7;box-shadow:inset 2px 0 #c486b8}.sidebar-foot{margin-top:auto;padding:16px 6px 0;border-top:1px solid var(--line);font-size:10px;color:#ded8e4}.sidebar-foot p{color:var(--dim);line-height:1.7}.paper-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--accent);margin-right:8px}
.app-shell{margin-left:188px}header{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:25px 28px 18px}header .eyebrow{font-size:10px;text-transform:none;letter-spacing:0}header h1{margin-top:4px}.header-actions{display:flex;align-items:center;gap:18px}.meta{text-align:right;font-size:10px;color:var(--dim)}.meta p{margin:2px 0}.snapshot-label{color:#d7d3de}.chat-jump{font-size:12px;text-decoration:none;border:1px solid var(--line);background:#1e1d24;padding:8px 12px;border-radius:6px;white-space:nowrap}.chat-jump span{padding-left:12px}
.workspace{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:20px;padding:0 28px 28px;align-items:start;max-width:1920px;margin:0 auto}.agent-picker{border:0;margin:0;padding:0;min-width:0;width:100%}.agent-picker legend{padding:0;margin:0 0 12px;color:var(--dim);font-size:10px}.agent-filter{position:absolute;width:1px;height:1px;opacity:0}.agent-tab{display:inline-block;padding:6px 12px;margin:0 4px 0 0;color:var(--dim);border:1px solid transparent;border-radius:5px;font-size:11px;cursor:pointer}.agent-tab:hover{color:var(--fg);background:#211e25}.agent-filter:checked+label{border-color:#483247;background:#302330;color:#e8c5e7}.agent-filter:focus-visible+label{outline:2px solid var(--gold);outline-offset:3px}
main{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-top:16px}section{grid-column:span 2;min-width:0;background:var(--panel);border:1px solid var(--line);border-radius:9px;padding:18px;scroll-margin-top:24px}section.wide{grid-column:1/-1}.section-top{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.section-top h2{margin:4px 0 0}.hero{background:#1b1920;border-color:#39303e}.hero-title{font-size:20px}.hero>p.dim{font-size:11px}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px;margin:20px 0}.metric{padding:13px 12px 11px;min-width:0;background:#28202d;border:1px solid #403046;border-radius:7px}.metric:nth-child(2){background:#29251b;border-color:#3c3727}.metric:nth-child(3){background:#1c2a27;border-color:#2e403b}.metric:nth-child(4){background:#222532;border-color:#34394a}.metric span{display:block;font-size:10px;line-height:1.5;color:#c1b8ca}.metric strong{display:block;font-size:24px;font-weight:500;letter-spacing:-.055em;font-variant-numeric:tabular-nums;margin:7px 0;overflow-wrap:anywhere}.metric:nth-child(2) strong{color:#d9d599}.metric:nth-child(3) strong{color:var(--green)}.metric:nth-child(4) strong{color:var(--blue)}.metric strong.bad{color:var(--red)}
.next-action{margin-top:14px;padding:14px 0 0;border-top:1px solid #39303e;display:grid;grid-template-columns:minmax(140px,1fr) minmax(0,2fr);gap:18px}.next-action p{font-size:12px;margin:5px 0}.next-action strong{font-size:14px;font-weight:500}.next-action pre{margin-bottom:0}.notice{padding:10px 14px;background:#211e25;border:1px solid #3b3040;border-radius:7px;min-width:0;font-size:11px}.notice.bad{border-color:#704449}main>aside.notice{margin:0}.notice summary{padding:0}.notice ul{margin-bottom:0}
.agent-summary{grid-column:span 1;display:grid;grid-template-columns:32px minmax(0,1fr);gap:0 9px;padding:12px;align-content:start;background:#18191c}.avatar-stage{grid-column:1;grid-row:1/3;width:32px;height:40px;display:flex;align-items:center;justify-content:center;background:#25232b;border-radius:6px}.avatar-stage img{width:30px;height:36px;object-fit:contain}.agent-summary .eyebrow{font-size:8px;letter-spacing:.02em;text-transform:none;align-self:end;overflow-wrap:anywhere}.agent-summary h2{margin:0;font-size:14px}.agent-summary .role{grid-column:1/-1;color:var(--dim);font-size:10px;min-height:30px;margin:9px 0}.talk-button{grid-column:1/-1;display:flex;align-items:center;justify-content:space-between;border:0;border-top:1px solid var(--line);background:none;color:#c8bad2;text-align:left;padding:8px 0 0;font-size:10px}.talk-button:hover{color:#f0cff1}.agent-owner{display:block;font-size:9px;text-transform:uppercase;letter-spacing:.09em;color:var(--dim);margin-bottom:4px}
.table-scroll{overflow:auto;max-width:100%;scrollbar-width:thin}table{width:100%;border-collapse:collapse;font-size:11px}th,td{text-align:left;padding:10px 8px;border-bottom:1px solid var(--line);vertical-align:top}th{font-weight:400;color:var(--dim);font-size:10px;white-space:nowrap}td.num{text-align:right;font-variant-numeric:tabular-nums}tbody tr:last-child td{border-bottom:0}tbody tr:hover{background:#24212a}.empty{padding:18px 14px;color:var(--dim);background:#15161a;border:1px solid #25252e;border-radius:6px;font-size:12px}.empty:before{content:'—';display:block;color:#665970;font-size:22px;margin-bottom:4px}.research-warning{font-size:11px;color:#e1b4d7;margin-bottom:14px}.research-study{display:block;min-width:120px}.research-study small{display:block;color:var(--dim);font-size:9px;font-weight:400}.r-chart{width:110px;height:32px;display:block}.research-legend{display:flex;gap:16px;flex-wrap:wrap;font-size:10px;color:var(--dim);margin:8px 0}.research-legend i{display:inline-block;width:6px;height:6px;border-radius:50%;background:#d39acc;margin-right:6px}.research-legend .median-key{background:#8fe1c7}dl{display:grid;grid-template-columns:minmax(90px,max-content) 1fr;gap:9px 14px;margin:0}dt{font-size:11px;color:var(--dim)}dd{margin:0;font-size:12px;overflow-wrap:anywhere}ul,ol{padding-left:18px}li{margin:6px 0}pre{padding:10px;background:#111216;border:1px solid var(--line);border-radius:5px;overflow:auto;font-size:11px;margin:10px 0}code{font-family:ui-monospace,Consolas,monospace}pre code{white-space:pre}summary{cursor:pointer;color:var(--dim);padding:8px 0;font-size:11px}details[open]>summary{color:var(--fg);margin-bottom:8px}.reasons{color:var(--red)}footer{padding:18px 28px;border-top:1px solid var(--line);color:var(--dim);font-size:10px}
.chat-dock{position:sticky;top:20px;display:flex;flex-direction:column;gap:10px;min-width:0;height:calc(100dvh - 40px);max-height:980px;min-height:660px;margin:0;padding:18px;background:#19181e;border:1px solid #38303e;border-radius:9px;scroll-margin-top:20px}.chat-heading{padding-bottom:10px;border-bottom:1px solid var(--line)}.chat-heading h2{font-size:17px;margin:2px 0 3px}.chat-heading p{color:var(--dim);font-size:10px;margin:0}.chat-heading .eyebrow{font-size:9px}.chat-label{display:block;font-size:10px;color:var(--dim);margin-bottom:4px}#chat-agent{width:100%;background:#211e27;border:1px solid #39323f;color:var(--fg);padding:8px 10px;border-radius:5px;font-size:11px}.chat-persona{display:flex;gap:10px;align-items:center}.chat-persona img{width:32px;height:36px;object-fit:contain;background:#302c36;padding:2px;border-radius:6px}.chat-persona strong{display:block;font-size:13px;font-weight:550}.chat-persona span{display:block;font-size:10px;color:var(--dim)}.chat-persona .local-badge{margin-left:auto;font:9px ui-monospace,Consolas,monospace;border:1px solid var(--line);border-radius:4px;padding:4px}.chat-snapshot{font-size:9px;color:var(--dim);margin:0;border-bottom:1px solid var(--line);padding-bottom:10px}.nova-button{background:#322638;color:#e6c7ee;border:1px solid #4d3756;border-radius:5px;padding:8px 10px;font-size:11px;text-align:left}.nova-button:hover{background:#413047}
#chat-log{flex:1;min-height:140px;overflow-y:auto;overscroll-behavior:contain;scrollbar-width:thin;scrollbar-color:#46374e transparent;padding-right:4px}.chat-placeholder{font-size:12px;color:var(--dim)}.chat-message{font-size:12px;overflow-wrap:anywhere;border-bottom:1px solid var(--line);padding:12px 0;margin-bottom:6px}.chat-message p{white-space:pre-wrap;margin:6px 0}.message-head{display:flex;align-items:center;gap:7px}.message-avatar{width:20px;height:22px;background:#302c36 center/contain no-repeat;border-radius:4px;flex-shrink:0}.message-name{color:#dec6e5;font-size:10px;font-weight:550}.message-time{margin-left:auto;color:#96909f;font-size:9px}.message-source{display:block;margin-top:10px;font-size:9px;color:var(--dim);line-height:1.5}.from-user{background:#2c2432;border:1px solid #423249;border-radius:7px;padding:10px 12px;margin:10px 0 4px 24px}.from-user .message-name{color:#d7c4df}.message-body{font-size:12px;line-height:1.7}.message-body p{white-space:normal;margin:6px 0}.message-body ul,.message-body ol{margin:6px 0;padding-left:18px}.message-body li{margin:3px 0}.message-body strong{font-weight:600;color:#f1e4f1}.message-body code{background:#111216;border:1px solid var(--line);border-radius:3px;padding:0 4px;font-size:11px}.message-heading{font-weight:600;color:#ead2ee;margin-top:12px!important}.message-body a{color:var(--gold);overflow-wrap:anywhere;text-underline-offset:3px}.thinking{display:flex;gap:8px;align-items:center;color:var(--dim)}.thinking .dots{animation:pulse 1.2s infinite;letter-spacing:2px}@keyframes pulse{0%,100%{opacity:.3}50%{opacity:1}}
#chat-prompts{display:flex;gap:5px;flex-wrap:wrap}.prompt-chip{background:#211e27;color:#cfbcd7;border:1px solid #393040;border-radius:5px;padding:6px 8px;font-size:10px;text-align:left}.prompt-chip:hover{background:#35273e}.composer{display:flex;align-items:flex-end;gap:6px;border:1px solid #514059;background:#131217;border-radius:7px;padding:8px}.composer:focus-within{border-color:var(--gold)}.composer textarea{flex:1;min-width:0;resize:vertical;min-height:46px;max-height:120px;background:none;border:0;color:var(--fg);padding:4px;font-size:12px}.composer textarea::placeholder{color:#93879f}.composer button{flex-shrink:0;width:30px;height:30px;border:0;border-radius:5px;background:#d4afd9;color:#231929;font-size:20px}.chat-bottom{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:7px;color:var(--dim);font-size:9px}.chat-buttons{display:flex;gap:10px}.chat-bottom button{border:0;background:none;color:#dbc0e2;font-size:10px;padding:3px 0}.chat-privacy{margin:0;font-size:9px;color:var(--dim);line-height:1.6}#chat-usage{font-variant-numeric:tabular-nums}body.chat-wide .workspace{grid-template-columns:minmax(0,1fr) minmax(400px,48%)}body.chat-wide .agent-summary{grid-column:span 2}body.chat-wide .metrics{grid-template-columns:repeat(2,minmax(0,1fr))}
@media(min-width:1750px){.workspace{grid-template-columns:minmax(0,1fr) 390px}.chat-dock{padding:22px}.message-body{font-size:13px}.agent-summary{padding:16px}}
@media(max-width:1390px){.sidebar{width:164px;padding:24px 12px}.app-shell{margin-left:164px}.workspace{padding:0 20px 24px;gap:16px;grid-template-columns:minmax(0,1fr) 310px}header{padding:22px 20px 18px}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.agent-summary{grid-column:span 2}.next-action{grid-template-columns:1fr;gap:5px}.header-actions{gap:10px}.meta{display:none}section{padding:16px}dl{grid-template-columns:1fr}dd{margin-top:-6px}.chat-dock{padding:14px}.sidebar nav a{padding:10px;font-size:11px}}
@media(max-width:1100px){.workspace,body.chat-wide .workspace{grid-template-columns:minmax(0,1fr)}.chat-dock{position:relative;top:auto;height:800px;max-height:none;min-height:660px}dl{grid-template-columns:minmax(90px,max-content) 1fr}dd{margin:0}.metrics{grid-template-columns:repeat(4,minmax(0,1fr))}.agent-summary{grid-column:span 1}.next-action{grid-template-columns:1fr 2fr;gap:18px}.chat-dock .message-body{font-size:13px}}
@media(max-width:760px){.sidebar{position:relative;inset:auto;width:100%;padding:12px 16px 0;border-right:0;border-bottom:1px solid var(--line)}.wordmark{font-size:21px;padding:0}.brand-mark{width:24px;height:24px;font-size:16px}.workspace-label,.nav-label,.sidebar-foot{display:none}.sidebar nav{display:flex;gap:4px;overflow-x:auto;padding:10px 0 0;scrollbar-width:thin}.sidebar nav a{flex-shrink:0;font-size:11px;padding:9px;margin:0 0 8px}.sidebar nav a span{display:none}.app-shell{margin-left:0}header{padding:18px 16px 14px}header h1{font-size:23px}.header-actions>.pill{display:none}.workspace,body.chat-wide .workspace{padding:0 16px 20px}.agent-summary,body.chat-wide .agent-summary{grid-column:span 2}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.agent-picker legend{font-size:9px}.agent-tab{padding:6px 10px;margin-right:2px}.next-action{grid-template-columns:1fr;gap:5px}section{grid-column:1/-1}.hero{padding:16px}.metric strong{font-size:25px}main{gap:12px}.table-scroll{margin-top:6px}footer{padding:16px}.chat-dock{padding:16px;height:850px}.chat-bottom{font-size:9px}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
@media print{.sidebar,.chat-dock,.agent-tab,.talk-button,.chat-jump,.skip-link{display:none}.app-shell{margin:0}.workspace{display:block}section{break-inside:avoid}body{background:white;color:black}pre{white-space:pre-wrap}}
"""
